body:
@Pitasi I hoped it would be possible to ignore certain directories by now as I have the same problem.

On at least Linux it is possbile to use the `LD_PRELOAD` trick to provide alternative versions of functions from e.g. glibc. So in this case I wrote a library that would catch all stat calls made by `starship` and would return info for a non-existing dir for git dirs we want to ignore.

`starship_ignore_some_git_dirs.c`: Change `git_dirs_to_ignore` array to  resolved absolute paths of git dirs you want starship to ignore.
```c
❯ cat starship_ignore_some_git_dirs.c
#define _GNU_SOURCE

#define LEN(arr) ((int) (sizeof (arr) / sizeof (arr)[0]))

#include <dlfcn.h>
#include <linux/limits.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

static int (*original_xstat)(int ver, const char *path,
                             struct stat *buf) = NULL;
static int (*original_xstat64)(int ver, const char *path,
                               struct stat64 *buf) = NULL;

bool ignore_some_git_dirs(const char *path) {
  // Add git directories to ignore.
  // Use "realpath dir_name" to get the resolved absolute path.
  char git_dirs_to_ignore[][PATH_MAX] = {
    "/path1/to/ignore/.git",
    "/path2/to/ignore/.git",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
  };

  for (int i = 0; i < LEN(git_dirs_to_ignore); i++) {
    // Stop checking git dirs to ignore on the first "" entry.
    if (git_dirs_to_ignore[i][0] == '\0') {
      return false;
    }

    // Check if the current requested path is a git directory
    // which we want to ignore.
    if (strcmp(path, git_dirs_to_ignore[i]) == 0) {
      return true;
    }
  }

  return false;
}


int __xstat(int ver, const char *path, struct stat *buf) {
  if (original_xstat == NULL) {
    original_xstat = dlsym(RTLD_NEXT, "__xstat");
  }

  //printf("xstat %s\n", path);

  if (ignore_some_git_dirs(path)) {
    // Call the original __xstat function on a non-existing dir,
    // so the unwanted git directory gets ignored.
    return original_xstat(ver, "/nonexisting_path", buf);
  } else {
    // Call the original __xstat function in all other cases.
    return original_xstat(ver, path, buf);
  }
}

int __xstat64(int ver, const char *path, struct stat64 *buf) {
  if (original_xstat64 == NULL) {
    original_xstat64 = dlsym(RTLD_NEXT, "__xstat64");
  }

  //printf("xstat64 %s\n", path);

  if (ignore_some_git_dirs(path)) {
    // Call the original __xstat64 function on a non-existing dir,
    // so the unwanted git directory gets ignored.
    return original_xstat64(ver, "/nonexisting_path", buf);
  } else {
    // Call the original __xstat64 function in all other cases.
    return original_xstat64(ver, path, buf);
  }
}
```

Compile our library so we can use it with `LD_PRELOAD`
```
gcc -Wall -fPIC -shared -o starship_ignore_some_git_dirs.so starship_ignore_some_git_dirs.c -ldl
```

In `~/.bashrc`:

```bash
starship_realpath="$(realpath "$(which starship)")";

ld_preload_so_starship_ignore_some_git_dirs='/path/to/starship_ignore_some_git_dirs.so';

# Enable starship and add LD_PRELOAD="${ld_preload_so_starship_ignore_some_git_dirs}" before each starship invokation.
eval "$(starship init bash | sed -e "s#--print-full-init#--print-full-init | sed 's@\"${starship_realpath}\"@LD_PRELOAD=\"${ld_preload_so_starship_ignore_some_git_dirs}\" \"${starship_realpath}\\\"@'#")"
```
